class Solution:
    def findPermutationDifference(self, s: str, t: str) -> int:
        # Create a mapping of character to its position in s
        s_pos = {}
        for i, char in enumerate(s):
            s_pos[char] = i

        # Create a mapping of character to its position in t
        t_pos = {}
        for i, char in enumerate(t):
            t_pos[char] = i

        # Calculate the permutation difference
        diff = 0
        for char in s:
            if char in t_pos:
                diff += abs(s_pos[char] - t_pos[char])

        return diff
```

