        min_sum = float('inf')

        for i in range(len(nums) - l + 1):
            for j in range(i + l - 1, len(nums)):
                if j - i + 1 <= r:
                    current_sum = sum(nums[i:j+1])
                    if current_sum > 0:
                        min_sum = min(min_sum, current_sum)

