class Solution:
    def numberOfSubstrings(self, s: str, k: int) -> int:
        n = len(s)
        count = 0
        for i in range(n):
            for j in range(i, n):
                count += 1
                # Count character frequencies in substring s[i:j+1]
                char_freq = {}
                for c in s[i:j+1]:
                    char_freq[c] = char_freq.get(c, 0) + 1

                # Check if any character appears >= k times
                if any(freq >= k for freq in char_freq.values()):
                    count += 1
        return count
