class Solution:
    def countOfSubstrings(self, word: str, k: int) -> int:
        vowels = {'a', 'e', 'i', 'o', 'u'}
        n = len(word)
        count = 0

        for i in range(n):
            # Find the first occurrence of all vowels starting from i
            vowel_start = i
            vowel_end = i

            # Expand to find the first substring that contains all vowels
            for j in range(i, n):
                if word[j] in vowels:
                    vowel_end = j
                    break

            # Count consonants in the substring from i to vowel_end
            consonant_count = 0
            for j in range(i, vowel_end + 1):
                if word[j] not in vowels:
                    consonant_count += 1

            # Check if consonant count matches k
            if consonant_count == k:
                count += 1

        return count
