from math import gcd
from functools import reduce
from operator import mul

class Solution:
    def maxScore(self, nums: List[int]) -> int:
        def gcd(a, b):
            while b:
                a, b = b, a % b
            return a

        def lcm(a, b):
            return (a * b) // gcd(a, b)

        def calculate_lcm_and_gcd(arr):
            if not arr:
                return 0, 0
            g = arr[0]
            for i in range(1, len(arr)):
                g = gcd(g, arr[i])
            l = arr[0]
            for i in range(1, len(arr)):
                l = lcm(l, arr[i])
            return l, g

        def remove_element_score(arr, removed_idx):
            remaining = arr[:removed_idx] + arr[removed_idx+1:]
            return calculate_lcm_and_gcd(remaining)

        # Calculate score with no removal
        l, g = calculate_lcm_and_gcd(nums)
        score = l * g

        # Try removing each element
        for i in range(len(nums)):
            remaining = nums[:i] + nums[i+1:]
            if not remaining:
                continue
            l, g = calculate_lcm_and_gcd(remaining)
            score = max(score, l * g)

        return score
